PRAGMA foreign_keys = ON;
CREATE TABLE hospital (id TEXT PRIMARY KEY, hcode TEXT NOT NULL UNIQUE, name_th TEXT NOT NULL, name_en TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE units (id TEXT PRIMARY KEY, hospital_id TEXT NOT NULL REFERENCES hospital(id), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE users (id TEXT PRIMARY KEY, hospital_id TEXT NOT NULL REFERENCES hospital(id), unit_id TEXT REFERENCES units(id), username TEXT NOT NULL COLLATE NOCASE UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('SystemAdmin','UnitAdmin','Staff')), work_scopes_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(work_scopes_json)), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), session_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts (key_hash TEXT PRIMARY KEY, count INTEGER NOT NULL, window_started_at INTEGER NOT NULL, blocked_until INTEGER);
CREATE TABLE revoked_sessions (jti TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, revoked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, hospital_id TEXT NOT NULL REFERENCES hospital(id), actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, detail_json TEXT, ip_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX audit_created_idx ON audit_log(created_at);
CREATE TABLE module_settings (hospital_id TEXT NOT NULL REFERENCES hospital(id), module_key TEXT NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), updated_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(hospital_id,module_key));
CREATE TABLE module_records (id TEXT PRIMARY KEY, hospital_id TEXT NOT NULL REFERENCES hospital(id), module_key TEXT NOT NULL, unit_id TEXT REFERENCES units(id), title TEXT NOT NULL, status TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX module_records_scope_idx ON module_records(hospital_id,module_key,unit_id);
CREATE TABLE patient_records (id TEXT PRIMARY KEY, hospital_id TEXT NOT NULL REFERENCES hospital(id), reference_code TEXT NOT NULL, care_need TEXT NOT NULL, legal_basis TEXT NOT NULL CHECK(legal_basis IN ('consent','vital-interests','public-task','legal-obligation')), consent_reference TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(hospital_id,reference_code));
